<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import type {ReceivableFilters} from '@quote/contracts';
import {ReceivablesController,createReceivablesState,receivableFilterForm,filtersDirty,restoreFilters,accountState,paymentStateLabel,paymentDate,paymentType,paymentReference,beijingToday} from '@quote/receivables-client';
import {beijingTime} from '@quote/archive-client';
import {request,mutate,pending} from '../api';
const props=defineProps<{locked:boolean}>();const emit=defineEmits<{(e:'manage-finance',target:{orderId:string;receivableId:string}):void;(e:'busy-changed',value:boolean):void;(e:'dirty-changed',value:boolean):void;(e:'failure',value:unknown):void}>();
const state=reactive(createReceivablesState()),filters=reactive(receivableFilterForm(state.applied)),ack=ref(false);
const controller=new ReceivablesController(request,(label,path,body)=>mutate(label,path,'POST',body),state,e=>emit('failure',e));
const ownBusy=computed(()=>state.listLoading||state.detailLoading||state.hospitalsLoading||state.working),locked=computed(()=>props.locked||ownBusy.value),writeLocked=computed(()=>locked.value||!!pending.value);
const dirty=computed(()=>filtersDirty(filters,state.applied)),pages=computed(()=>state.page?Math.max(1,Math.ceil(state.page.total/state.page.pageSize)):1);
const ar=computed(()=>state.detail?.receivable),corrected=computed(()=>state.detail?.payments.find(p=>p.id===state.form.correctsPaymentRecordId));
const formLocked=computed(()=>writeLocked.value||ar.value?.paymentState==='settled'||!!state.review);
const owners=[['mine','本人负责'],['','全部可查看'],['readonly','其他负责人（只读）']],payments=[['outstanding','全部未收齐'],['','全部回款情况'],['unpaid','未收款'],['partial','部分回款'],['settled','已结清']],dueStates=[['','全部到期情况'],['upcoming','未到期'],['due','今日到期'],['overdue','逾期未收']];
const hospitalOptions=computed(()=>[{id:'',name:'全部可查看医院'},...state.hospitals]);
const picked=(e:unknown)=>Number((e as {detail:{value:string}}).detail.value),date=(e:unknown)=>(e as {detail:{value:string}}).detail.value;
const label=(options:string[][],value:string)=>options.find(s=>s[0]===value)?.[1]||options[0][1];
watch(ownBusy,value=>emit('busy-changed',value),{flush:'sync',immediate:true});watch(()=>state.review,()=>{ack.value=false;});
const entryDirty=computed(()=>hasEntry()||!!state.review);
watch(entryDirty,value=>emit('dirty-changed',value),{flush:'sync',immediate:true});
function canLeave(){return !ownBusy.value&&!entryDirty.value&&!pending.value;}
function abandon(){if(writeLocked.value)return;controller.cancelCorrection();}
function retainEntry(){if(!entryDirty.value)return false;state.writeError='有未提交回款，请先完成登记或选择放弃并清空未提交回款。';return true;}
function paused(value:unknown){return (value as {paused?:boolean})?.paused===true;}
function hasEntry(){return !!(state.form.amount||state.form.paidDate||state.form.remark||state.form.correctsPaymentRecordId||state.voidPaymentId);}
function manageFinance(){if(locked.value||!!pending.value||!ar.value||state.review)return;if(hasEntry()){state.writeError='已有未提交回款内容，请先完成登记或清空后再查看账期与异常。';return;}emit('manage-finance',{orderId:ar.value.orderId,receivableId:ar.value.id});}
function originalReference(id:string){return paymentReference(state.detail?.payments.find(p=>p.id===id));}
function guard(work:()=>void){try{state.writeError='';work();}catch(e){state.writeError=(e as Error).message;}}
function setDate(e:unknown){state.form.paidDate=date(e);controller.invalidateReview();}
async function query(){if(locked.value)return;await controller.query({...filters} as ReceivableFilters);}
async function reset(){if(locked.value)return;Object.assign(filters,receivableFilterForm(createReceivablesState().applied));await query();}
async function open(id:string){if(locked.value)return;await controller.open(id);}
async function back(){if(locked.value||retainEntry())return;restoreFilters(filters,state.applied);await controller.back();}
async function move(n:number){if(locked.value)return;restoreFilters(filters,state.applied);await controller.move(n);}
async function refresh(){if(locked.value||retainEntry())return;if(state.mode==='detail')await controller.open(state.selectedId);else{restoreFilters(filters,state.applied);await controller.back();}}
// Recovery is called after the parent's operation lock has been released. Epochs also cancel any initial list read.
async function openAfterRecovery(id:string){await controller.open(id);if(state.detail)state.notice='原回款操作已确认提交，余额已重新读取。';}
async function commit(){if(writeLocked.value||!ack.value)return;try{await controller.commit();}catch{/* shared error is visible; pending retains original request */}}
defineExpose({refresh,openAfterRecovery,canLeave});
onMounted(()=>Promise.all([controller.hospitals(),controller.query(state.applied)]));onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);emit('dirty-changed',false);});
</script>
<template>
 <view class="receivables">
  <template v-if="state.mode==='list'">
   <text class="eyebrow">按订单跟进 · 默认本人未收齐</text><text class="title">回款台账</text><text class="subtle">医院最终确认形成应收，分次回款按订单登记。</text>
   <view class="filters"><label class="field"><text>查看范围</text><picker :range="owners.map(s=>s[1])" :value="Math.max(0,owners.findIndex(s=>s[0]===filters.ownership))" :disabled="locked" @change="filters.ownership=owners[picked($event)][0]"><view class="select">{{label(owners,filters.ownership)}} ⌄</view></picker></label><label class="field"><text>医院</text><picker :range="hospitalOptions.map(h=>h.name)" :value="Math.max(0,hospitalOptions.findIndex(h=>h.id===filters.hospitalId))" :disabled="locked" @change="filters.hospitalId=hospitalOptions[picked($event)].id"><view class="select">{{hospitalOptions.find(h=>h.id===filters.hospitalId)?.name||'全部可查看医院'}} ⌄</view></picker></label>
    <label class="field"><text>回款情况</text><picker :range="payments.map(s=>s[1])" :value="Math.max(0,payments.findIndex(s=>s[0]===filters.paymentState))" :disabled="locked" @change="filters.paymentState=payments[picked($event)][0]"><view class="select">{{label(payments,filters.paymentState)}} ⌄</view></picker></label><label class="field"><text>到期情况</text><picker :range="dueStates.map(s=>s[1])" :value="Math.max(0,dueStates.findIndex(s=>s[0]===filters.dueState))" :disabled="locked" @change="filters.dueState=dueStates[picked($event)][0]"><view class="select">{{label(dueStates,filters.dueState)}} ⌄</view></picker></label>
    <label class="field"><text>实际接收日期（起）</text><picker mode="date" :value="filters.receivedFrom" :disabled="locked" @change="filters.receivedFrom=date($event)"><view class="select">{{filters.receivedFrom||'不限'}} ⌄</view></picker><button v-if="filters.receivedFrom" class="text-button" :disabled="locked" @click="filters.receivedFrom=''">清除</button></label><label class="field"><text>实际接收日期（止）</text><picker mode="date" :value="filters.receivedTo" :disabled="locked" @change="filters.receivedTo=date($event)"><view class="select">{{filters.receivedTo||'不限（含当天）'}} ⌄</view></picker><button v-if="filters.receivedTo" class="text-button" :disabled="locked" @click="filters.receivedTo=''">清除</button></label>
    <label class="field wide"><text>订单号 / 医院</text><input v-model="filters.keyword" maxlength="100" :disabled="locked" placeholder="输入完整或部分文字" /></label>
   </view><view class="actions"><button class="primary" :disabled="locked" @click="query">查询</button><button :disabled="locked" @click="reset">重置</button></view>
   <view v-if="dirty" class="notice">筛选已修改，点击查询后生效；当前仍显示已查询条件。</view><view v-if="state.hospitalsError" class="error">医院筛选读取失败：{{state.hospitalsError}}<button :disabled="locked" class="text-button" @click="controller.hospitals()">重试</button></view><view v-if="state.listError" class="error">查询失败：{{state.listError}}<button :disabled="locked" class="text-button" @click="back">重新查询</button></view><text v-if="state.listLoading" class="empty">正在读取回款台账…</text>
   <template v-if="state.page&&!state.listLoading"><view class="results"><text>共 {{state.page.total}} 单应收</text><text class="tiny">金额单位：元 · 到期日顺序</text></view>
    <button v-for="item in state.page.items" :key="item.id" class="order-row" :disabled="locked" @click="open(item.id)"><view class="row-heading"><text class="hospital">{{item.hospitalName}}</text><text class="tiny">{{accountState(item)}} ›</text></view><text class="subtle small">{{item.orderNo}} · 接收 {{item.receivedDate}}</text><view class="row-facts"><view><text class="tiny">应收</text><text>{{item.amount}}</text></view><view><text class="tiny">有效已收</text><text>{{item.paid}}</text></view><view><text class="tiny">未收余额</text><text class="amount">{{item.balance}}</text></view></view><text class="subtle small">{{item.paymentState==='settled'?'':paymentStateLabel(item)+' · '}}到期 {{item.dueDate}}</text><text v-if="paused(item)" class="subtle small">异常暂停催收 · 原金额与到期日保留</text><text class="subtle small">{{item.owner.name}} · {{item.writable?'订单负责销售':'只读查阅'}}</text></button><text v-if="!state.page.items.length" class="empty">没有符合当前筛选的应收。</text>
    <view class="pagination"><button :disabled="locked||state.page.page<=1" @click="move(state.page!.page-1)">上一页</button><text>第 {{state.page.page}} / {{pages}} 页</text><button :disabled="locked||state.page.page>=pages" @click="move(state.page!.page+1)">下一页</button></view><text class="tiny">读取于 {{beijingTime(state.page.asOf)}}</text>
   </template><text class="footnote">全缺货不产生应收；尚未医院确认及未核实的历史补录不进入台账。</text>
  </template>
  <template v-else>
   <view class="actions"><button :disabled="locked" @click="back">← 返回原筛选</button><button :disabled="locked" @click="refresh">载入最新余额</button></view><text v-if="state.detailLoading" class="empty">正在读取应收和回款记录…</text><view v-if="state.detailError" class="error">详情读取失败：{{state.detailError}}</view><view v-if="state.notice" class="notice">{{state.notice}}</view><view v-if="state.writeError" class="error">{{state.writeError}}</view>
   <template v-if="ar&&state.detail"><text class="eyebrow detail-number">{{ar.orderNo}}</text><text class="title">{{ar.hospitalName}}</text><text class="subtle small">{{accountState(ar)}} · 负责人 {{ar.owner.name}}</text><view class="account-facts"><view><text class="tiny">应收 / 元</text><text>{{ar.amount}}</text></view><view><text class="tiny">有效已收 / 元</text><text>{{ar.paid}}</text></view><view><text class="tiny">未收余额 / 元</text><text class="amount">{{ar.balance}}</text></view></view><text class="subtle small">实际接收 {{ar.receivedDate}} · 账期 {{ar.paymentTermDays}} 天</text><text class="subtle small">到期日 {{ar.dueDate}} · 部分回款不重置到期日</text>
    <view class="actions"><button :disabled="locked||!!pending||!!state.review" @click="manageFinance">查看账期 / 异常 →</button><button v-if="hasEntry()" :disabled="writeLocked||!!state.review" @click="abandon">放弃并清空未提交回款</button></view><view v-if="paused(ar)" class="notice">异常暂停催收；原金额与到期日保留，不表示结清或退款完成。</view><view v-if="!ar.writable" class="notice">本单只读，回款及误录作废由订单负责销售员处理。</view>
    <view v-if="ar.writable" class="entry"><text class="section-title">{{state.form.correctsPaymentRecordId?'关联作废记录重录':'登记本次回款'}}</text><text class="subtle small">仅登记此订单实际收到的一笔款。</text><view v-if="corrected" class="notice">原记录 {{paymentReference(corrected)}}<button class="text-button" :disabled="writeLocked" @click="controller.cancelCorrection()">取消关联</button></view><view v-if="ar.paymentState==='settled'" class="notice">本单已结清，不能追加正数回款；误录仍可选择有效记录作废。</view>
     <label class="field"><text>实际回款金额 / 元</text><input v-model="state.form.amount" type="digit" :disabled="formLocked" placeholder="如 1000.00" @input="controller.invalidateReview()" /></label><label v-if="!(corrected?.recordType==='historical_opening'&&corrected.paidDate===null)" class="field"><text>实际回款日期</text><picker mode="date" :value="state.form.paidDate||''" :end="beijingToday()" :disabled="formLocked" @change="setDate"><view class="select">{{state.form.paidDate||'请选择实际回款日期'}} ⌄</view></picker></label><text v-else class="subtle small">原历史累计回款日期未知，本次更正继续保留未知。</text><label class="field"><text>备注（可选）</text><textarea v-model="state.form.remark" maxlength="500" :disabled="formLocked" @input="controller.invalidateReview()" /></label><text class="tiny">实际日期与录入日期分别保存，不以今天代替实际日期。</text><button class="primary full" :disabled="formLocked" @click="guard(()=>controller.reviewPayment())">复核本次回款</button>
    </view>
    <view class="records"><text class="section-title">回款记录</text><text class="subtle small">有效与已作废记录均保留。</text><text v-if="!state.detail.payments.length" class="empty">暂无回款登记记录。</text><view v-for="p in state.detail.payments" :key="p.id" class="payment-record"><view class="row-heading"><text class="record-amount">{{p.amount}} 元</text><text class="tiny">{{p.status==='active'?'有效':'已作废'}}</text></view><text class="subtle small">{{paymentType(p)}} · {{paymentDate(p)}}</text><text class="record-fact">备注：{{p.remark||'—'}}</text><text class="record-fact">原记录人：{{p.recordedByName}}</text><text class="record-fact">原记录时间：{{beijingTime(p.recordedAt)}}</text><template v-if="p.status==='void'"><text class="record-fact">作废原因：{{p.voidReason}}</text><text class="record-fact">作废人：{{p.voidedByName}}</text><text class="record-fact">作废时间：{{beijingTime(p.voidedAt)}}</text></template><text v-if="p.correctsPaymentRecordId" class="subtle small reference">关联更正原记录：{{originalReference(p.correctsPaymentRecordId)}}</text><view v-if="ar.writable" class="actions record-actions"><button v-if="p.status==='active'" :disabled="writeLocked" @click="state.voidPaymentId=p.id;state.voidReason='';controller.invalidateReview()">作废误录</button><button v-else :disabled="writeLocked||ar.paymentState==='settled'" @click="guard(()=>controller.correct(p.id))">关联原记录重新登记</button></view>
     <view v-if="state.voidPaymentId===p.id" class="void-entry"><text class="subtle small">仅更正台账，不表示发生实际退款。</text><label class="field"><text>作废原因</text><textarea v-model="state.voidReason" maxlength="500" :disabled="writeLocked||!!state.review" @input="controller.invalidateReview()" /></label><view class="actions"><button :disabled="writeLocked" @click="state.voidPaymentId='';controller.invalidateReview()">取消</button><button :disabled="writeLocked||!!state.review" @click="guard(()=>controller.reviewVoid())">复核作废</button></view></view>
    </view></view>
   </template>
  </template>
  <view v-if="state.review" class="overlay"><view class="dialog" role="dialog" aria-modal="true"><text class="eyebrow">提交前复核</text><text class="section-title">{{state.review.kind==='payment'?'登记本次回款':'作废原回款'}}</text><view class="review-facts"><text>医院：{{state.review.hospitalName}}</text><text>订单：{{state.review.orderNo}}</text><text>金额：{{state.review.kind==='payment'?state.review.body.amount:state.review.payment?.amount}} 元</text><text>实际日期：{{state.review.kind==='payment'?(state.review.body.paidDate||'日期未知（历史累计）'):paymentDate(state.review.payment!)}}</text><template v-if="state.review.kind==='payment'"><text>备注：{{state.review.body.remark||'—'}}</text><text v-if="state.review.body.correctsPaymentRecordId">关联原记录：{{originalReference(String(state.review.body.correctsPaymentRecordId))}}</text></template><template v-else><text>作废原因：{{state.review.body.reason}}</text><text>原记录人：{{state.review.payment?.recordedByName}}</text><text>原记录时间：{{beijingTime(state.review.payment?.recordedAt)}}</text></template><text class="amount">未收余额：{{state.review.balanceBefore}} → {{state.review.balanceAfter}} 元</text></view><checkbox-group @change="ack=($event as any).detail.value.includes('ack')"><label class="ack"><checkbox value="ack" :checked="ack" :disabled="state.working" color="#215f46" /><text>{{state.review.kind==='payment'?'已核对订单、金额与实际日期，未重复登记。':'已核对原记录与原因；作废仅更正台账。'}}</text></label></checkbox-group><view class="actions"><button :disabled="state.working" @click="controller.invalidateReview()">返回修改</button><button class="primary" :disabled="writeLocked||!ack" @click="commit">{{state.working?'正在提交…':state.review.kind==='payment'?'确认登记':'确认作废'}}</button></view></view></view>
 </view>
</template>
<style scoped>
.receivables{width:100%;min-width:0;padding:18px 0 30px;color:#24382f;overflow:hidden}.eyebrow{display:block;font-size:11px;color:#7a897e;margin:4px 0 8px}.title{display:block;font-size:25px;font-weight:600;margin-bottom:12px;line-height:1.35}.subtle{display:block;color:#77877c;font-size:12px;line-height:1.7}.small{font-size:11px}.tiny{display:block;font-size:10px;line-height:1.7;color:#7b8d80}.filters{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 12px;padding:24px 0 18px}.field{display:block;min-width:0;margin:16px 0}.filters .field{margin:0}.wide{grid-column:1/-1}.field>text{display:block;font-size:11px;color:#53685c;margin-bottom:7px}.field input,.select,.field textarea{height:44px;padding:10px;background:#fff;border:1px solid #cfdbd2;border-radius:4px;font-size:13px;line-height:24px;box-sizing:border-box;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%}.field textarea{height:88px;white-space:normal}.field input:disabled,.field textarea:disabled{opacity:.6}button{font-size:12px;background:#fff;color:#215f46;border:1px solid #cfdbd2;border-radius:4px;line-height:24px;padding:8px 11px;min-height:44px;margin:0;transition:background .15s;white-space:normal}button:after{border:0}button[disabled]{opacity:.45}.primary{background:#215f46;color:#fff;border-color:#215f46}.full{width:100%;margin-top:18px}.actions{display:flex;gap:10px;padding:8px 0 18px}.actions button{flex:1}.results{display:flex;justify-content:space-between;align-items:center;padding:23px 0 5px;font-size:12px;border-top:1px solid #dfe7e1}.order-row{display:block;text-align:left;width:100%;padding:20px 0;border:0;border-bottom:1px solid #dfe7e1;border-radius:0;font-size:12px;white-space:normal}.row-heading{display:flex;justify-content:space-between;gap:12px;margin-bottom:7px;align-items:start}.hospital{font-size:16px;font-weight:550}.row-facts,.account-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:16px 0 12px;line-height:1.7;font-variant-numeric:tabular-nums}.row-facts>view>text,.account-facts>view>text{display:block}.amount{font-weight:600;color:#215f46}.pagination{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:22px 0 12px;font-size:11px;color:#74877a}.empty{display:block;padding:30px 0;font-size:12px;color:#7a8a7e}.footnote{display:block;font-size:10px;color:#859488;line-height:1.7;margin-top:20px}.error{padding:12px;color:#9b3e32;background:#fbf2ef;font-size:12px;line-height:1.7;white-space:pre-wrap;margin:14px 0}.notice{font-size:11px;line-height:1.7;color:#215f46;background:#eef5f0;padding:12px;margin:14px 0;border-left:2px solid #215f46}.text-button{border:0;padding:6px 0;min-height:32px;display:inline-block;background:transparent;font-size:11px}.detail-number{margin-top:20px;overflow-wrap:anywhere}.account-facts{font-size:16px;padding:20px 0;border-top:1px solid #dfe7e1;border-bottom:1px solid #dfe7e1;margin:22px 0 16px}.entry,.records{padding-top:26px;margin-top:22px;border-top:1px solid #dfe7e1}.section-title{font-size:17px;font-weight:550;display:block;margin-bottom:9px}.payment-record{padding:23px 0;border-bottom:1px solid #dfe7e1}.record-amount{font-size:18px;font-weight:550}.record-fact{display:block;font-size:11px;line-height:1.8;margin:7px 0;overflow-wrap:anywhere;white-space:pre-wrap}.record-actions{margin-top:14px;padding-bottom:0}.reference{overflow-wrap:anywhere;margin-top:10px;font-size:10px}.void-entry{padding:16px 0 0}.overlay{position:fixed;inset:0;background:#15251b66;display:flex;align-items:flex-end;justify-content:center;z-index:20}.dialog{background:#fff;padding:26px 22px calc(24px + env(safe-area-inset-bottom));width:100%;max-width:600px;box-sizing:border-box;max-height:90vh;overflow-y:auto;animation:enter .16s ease-out}.review-facts{display:grid;gap:12px;padding:22px 0;font-size:12px;line-height:1.7;overflow-wrap:anywhere;white-space:pre-wrap}.ack{display:flex;align-items:start;gap:8px;font-size:11px;line-height:1.7;margin:15px 0 22px}.ack checkbox{transform:scale(.8);transform-origin:top left;width:25px;flex-shrink:0}.ack text{flex:1}@keyframes enter{from{opacity:.6;transform:translateY(4px)}to{opacity:1;transform:none}}@media(min-width:700px){.dialog{margin-bottom:8vh}.overlay{align-items:center}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
